UPDATE catalogue_products SET
code=(SELECT m.code FROM _torkcraft_touch365_0052 m WHERE m.supplier_code=catalogue_products.code),
name=(SELECT m.name FROM _torkcraft_touch365_0052 m WHERE m.supplier_code=catalogue_products.code),
active=1,updated_by='system:torkcraft-touch365-2026-10-29',updated_at=datetime('now')
WHERE created_by IN ('system:torkcraft-catalogue-2026-10-27','system:selected-torkcraft-2026-10-29','system:torkcraft-core-holesaws-2026-10-29','system:torkcraft-touch365-2026-10-29') AND code IN (SELECT supplier_code FROM _torkcraft_touch365_0052 WHERE supplier_code<>'')
AND NOT EXISTS (SELECT 1 FROM catalogue_products target JOIN _torkcraft_touch365_0052 m ON upper(trim(target.code))=upper(m.code) WHERE m.supplier_code=catalogue_products.code);
--> statement-breakpoint
INSERT INTO catalogue_products(code,name,description,category,image_key,image_name,image_type,active,created_by,created_at,updated_by,updated_at)
SELECT m.code,m.name,'','Tork Craft',m.image_key,m.code||'.jpg','',1,'system:torkcraft-touch365-2026-10-29',datetime('now'),'system:torkcraft-touch365-2026-10-29',datetime('now') FROM _torkcraft_touch365_0052 m
WHERE NOT EXISTS (SELECT 1 FROM catalogue_products p WHERE upper(trim(p.code))=upper(m.code));
