UPDATE catalogue_products SET active=1,image_key=CASE WHEN coalesce(image_key,'')='' THEN (SELECT m.image_key FROM _torkcraft_touch365_0052 m WHERE m.code=catalogue_products.code) ELSE image_key END,updated_by='system:torkcraft-touch365-2026-10-29',updated_at=datetime('now')
WHERE created_by IN ('system:torkcraft-catalogue-2026-10-27','system:selected-torkcraft-2026-10-29','system:torkcraft-core-holesaws-2026-10-29','system:torkcraft-touch365-2026-10-29') AND code IN (SELECT code FROM _torkcraft_touch365_0052);
